    vowels = {'a', 'e', 'i', 'o', 'u'}
    consonants = set(word) - vowels

    for i in range(len(word)):
        if word[i] in vowels:
            if i > 0 and word[i-1] in consonants:
                if i < len(word) - 1 and word[i+1] in consonants:
                    return word[i]
            elif i < len(word) - 1 and word[i+1] in consonants:
                return word[i]

    return ""
