def get_max_triples(n):
    """
    You are given a positive integer n. You have to create an integer array a of length n.
        For each i (1 ≤ i ≤ n), the value of a[i] = i * i - i + 1.
        Return the number of triples (a[i], a[j], a[k]) of a where i < j < k, 
    and a[i] + a[j] + a[k] is a multiple of 3.

    Example :
        Input: n = 5
        Output: 1
        Explanation: 
        a = [1, 3, 7, 13, 21]
        The only valid triple is (1, 7, 13).
    """
    # Generate array a where a[i] = i * i - i + 1
    a = [i * i - i + 1 for i in range(1, n + 1)]

    # Count occurrences of each remainder when divided by 3
    remainder_counts = {}
    for x in a:
        remainder_counts[x % 3] = remainder_counts.get(x % 3, 0) + 1

    # Count valid triples where sum of remainders is divisible by 3
    count = 0
    for r1 in range(3):
        for r2 in range(3):
            for r3 in range(3):
                if (r1 + r2 + r3) % 3 == 0:
                    if r1 == 0 and r2 == 0 and r3 == 0:
                        count += remainder_counts[0] * remainder_counts[0] * remainder_counts[0]
                    elif r1 == 1 and r2 == 1 and r3 == 1:
                        count += remainder_counts[1] * remainder_counts[1] * remainder_counts[1]
                    elif r1 == 2 and r2 == 2 and r3 == 2:
                        count += remainder_counts[2] * remainder_counts[2] * remainder_counts[2]
                    elif r1 + r2 + r3 == 3:
                        count += remainder_counts[r1] * remainder_counts[r2] * remainder_counts[r3]
                    elif r1 + r2 + r3 == 6:
                        count += remainder_counts[r1] * remainder_counts[r2] * remainder_counts[r3]
                    elif r1 + r2 + r3 == 9:
                        count += remainder_counts[r1] * remainder_counts[r2] * remainder_counts[r3]

    return count
